namespace sv_f40ad14d37bd40eaa53cb3075cfee00a.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single circuit.
/// Components subscribe to OnChange to react when the warehouse is switched.
/// </summary>
public class WarehouseStateService
{
    public string CurrentWarehouseId { get; private set; } = "WH-001";

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Region"),
        ("WH-003", "Warehouse C — West Region"),
    };

    public void SetWarehouse(string warehouseId)
    {
        if (CurrentWarehouseId == warehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_f40ad14d37bd40eaa53cb3075cfee00a.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit gets its own instance so users don't interfere with each other.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate varying results per warehouse
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling starts on first subscriber.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Call when a component is disposed. Polling stops when last subscriber leaves.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _timer?.Dispose();
        _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _timer?.Dispose();
        _timer = null;
    }

    private async void PollCallback(object? state)
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        await NotifySubscribers();
    }

    private void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately poll the new warehouse
        if (_timer is not null)
        {
            _ = Task.Run(async () =>
            {
                CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                await NotifySubscribers();
            });
        }
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        StopPolling();
    }
}

