@using sv_f40ad14d37bd40eaa53cb3075cfee00a.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            @onchange="OnWarehouseChanged" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id" selected="@(wh.Id == WarehouseState.CurrentWarehouseId)">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_f40ad14d37bd40eaa53cb3075cfee00a.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge" title="Low stock alerts">
    ⚠️ <span class="badge bg-danger">@AlertService.CurrentAlertCount</span>
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        AlertService.Subscribe();
    }

    private async Task OnAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        AlertService.Unsubscribe();
    }
}

