<div class="card mb-4">
    <div class="card-header">
        <strong>Current Warehouse:</strong> @GetWarehouseName()
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4 text-danger">@AlertService.CurrentAlertCount</p>
        <p class="text-muted">
            Items below minimum stock level at <em>@WarehouseState.CurrentWarehouseId</em>.
            Auto-refreshes every 10 seconds.
        </p>
    </div>
</div>

<div class="card">
    <div class="card-body">
        <h5 class="card-title">How It Works</h5>
        <ul>
            <li>Select a warehouse from the dropdown in the top bar.</li>
            <li>All components update automatically via a shared scoped service.</li>
            <li>Polling runs only while this dashboard is visible.</li>
            <li>Each user session maintains independent state.</li>
        </ul>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        AlertService.Subscribe();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task OnAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name ?? "Unknown";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        AlertService.Unsubscribe();
    }
}

